switch (выражение) {
    case значение1:
        // код
        break;

    case значение2:
        // код
        break;

    default:
        // код
}

let day = 3;

switch (day) {
    case 1:
        console.log("Понедельник");
        break;

    case 2:
        console.log("Вторник");
        break;

    case 3:
        console.log("Среда");
        break;

    default:
        console.log("Неизвестный день");
}

let day = 2;

switch (day) {
    case 1:
        console.log("Понедельник");

    case 2:
        console.log("Вторник");

    case 3:
        console.log("Среда");
}

let day = 6;

switch (day) {
    case 6:
    case 7:
        console.log("Выходной");
        break;

    default:
        console.log("Рабочий день");
}

let color = "green";

switch (color) {
    case "red":
        console.log("Красный");
        break;

    case "blue":
        console.log("Синий");
        break;

    default:
        console.log("Другой цвет");
}

switch ("5") {
    case 5:
        console.log("Совпало");
        break;

    default:
        console.log("Не совпало");
}
